  dealId: deal.dealId ?? null,
  customer_name: deal.customer_name ?? null,
  email: deal.email ?? null,
  lead_id: leadId,
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    not_verified: NOT_VERIFIABLE_HERE,
    purchase_row: purchaseRow,
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified'
        + (purchaseRow && /already recorded/.test(purchaseRow) ? '; this deal was already on file and was not written twice' : ''),
