// precisely the outcome the caller asked for, and the table is protected by the
// unique index itself, not by the Prefer header. Anything else is a sale that
// did NOT reach the database and is re-thrown, so it still fails the run and
// still reaches the error workflow. Silence is never treated as success here.

const j = $input.first().json || {};

if (j.error === undefined) {
  return [{ json: { purchase_row: 'written' } }];
}

let blob;
try { blob = JSON.stringify(j); } catch (e) { blob = String(j); }

const isDuplicate = /23505|duplicate key|already exists/i.test(blob)
  || /"(httpCode|status)"\s*:\s*"?409\b/.test(blob);

