  if (!key) {
    throw new Error('Rejected: closed-won deal has neither a deal_id nor a lead_email/customer name to derive one from. Keys received: ' + Object.keys(d).join(', '));
  }
  dealId = 'auto:' + key.toLowerCase() + '|' + (closedAt || 'no-close-date');
}

