const claimed = String(d.tenant_id || raw.tenant_id || '');

// Which door? `$()` throws for a node that did not run in this execution.
let viaWebhook = true;
try { $('Auth OK?').all(); } catch (e) { viaWebhook = false; }

let tenant = null;
let tenantSource = 'unresolved';

if (viaWebhook) {
  let ids = [];
  try {
    ids = Array.from(new Set(
      $('Tenant For JWT User').all()
        .map((i) => (i && i.json ? i.json.tenant_id : null))
        .filter(Boolean)
        .map(String)
    ));
  } catch (e) { ids = []; }
  if (ids.length > 1) {
    throw new Error('[NEXUS-UNATTRIBUTED] Closed-won sync aborted: the authenticated user is a member of ' + ids.length + ' dealerships. This endpoint will not choose one on their behalf.');
  }
  if (ids.length === 0 || !NEXUS_UUID.test(ids[0])) {
    throw new Error('[NEXUS-UNATTRIBUTED] Closed-won sync aborted: the authenticated user has no tenant_members row. A dealership is never taken from the request body.');
  }
  if (claimed && claimed.toLowerCase() !== ids[0].toLowerCase()) {
    throw new Error('[NEXUS-UNATTRIBUTED] Closed-won sync aborted: caller asserted tenant_id ' + claimed + ' but is a member of ' + ids[0] + '. tenant_id is not a caller-selectable field.');
  }
  tenant = ids[0];
  tenantSource = 'jwt_tenant_member';
} else {
  if (NEXUS_UUID.test(claimed)) {
    tenant = claimed;
    tenantSource = 'internal_caller';
  } else if (nexusKeys.length === 1 && NEXUS_UUID.test(String(nexusMap[nexusKeys[0]] || ''))) {
    tenant = String(nexusMap[nexusKeys[0]]);
    tenantSource = 'sole_configured_tenant';
  } else {
    throw new Error('[NEXUS-UNATTRIBUTED] Closed-won sync aborted: the internal caller supplied no resolvable tenant_id and ' + nexusKeys.length + ' dealerships are configured. Refusing rather than filing this sale under a guess.');
  }
}
const parts = [
  customer ? 'Customer: ' + customer : null,
  email ? 'Email: ' + email : null,
  vehicle ? 'Vehicle: ' + vehicle : null,
  (amount !== undefined && amount !== null && amount !== '') ? 'Deal value: AED ' + amount : null,
  closedAt ? 'Closed at: ' + closedAt : null,
  clean(d.notes) ? 'Notes: ' + clean(d.notes) : null
].filter(Boolean);

const dealText = parts.join('. ');
if (!dealText) throw new Error('Rejected: deal ' + dealId + ' produced no text to embed.');

// Carry the structured fields through as well. `Record Purchase` needs them to
// write the actual purchase_history row; the embedding chain reads only dealId
// and dealText and is unaffected by the extra keys.
return [{ json: {
  dealId,
  dealText,
  customer_name: customer,
  email,
  phone: clean(d.phone) || clean(d.lead_phone),
  vehicle,
  amount_aed: (amount === undefined || amount === '') ? null : amount,
  purchase_date: closedAt,
  lead_id: leadId,
  tenant_id: tenant,
  tenant_source: tenantSource
} }];

const response = $input.first().json;
const dealId = $('Format Deal Text').first().json.dealId;
const dealText = $('Format Deal Text').first().json.dealText;
// 2 Sep 2026: the tenant is carried through so the pgvector row is stamped with
// the dealership whose deal it is, rather than the unattributed default.
const tenantId = $('Format Deal Text').first().json.tenant_id || null;

const embedding = response?.data?.[0]?.embedding;

// Never fall back to a zero vector: writing 1536 zeros into pgvector silently
// poisons the knowledge base and every similarity search after it. Fail loudly.
if (!Array.isArray(embedding) || embedding.length !== 1536) {
  throw new Error(
    'Embedding generation failed for deal ' + dealId + '. ' +
    'Nothing was written to deals_embeddings. Response: ' +
    JSON.stringify(response).substring(0, 400)
  );
}

return [{ json: { dealId, dealText, tenant_id: tenantId, embedding: JSON.stringify(embedding) } }];

// Every node whose success the Audit Log below is about to claim.
//
// 2 Sep 2026: this list used to hold the pgvector write alone, and named the
// purchase_history write under NOT_VERIFIABLE_HERE because 'Record Purchase'
// sat on the other branch out of Format Deal Text and, by node position under
// executionOrder v1, ran AFTER this one. That is no longer true. The purchase
// branch (Lookup Lead By Email -> Attach Lead Id -> Record Purchase ->
// Confirm Purchase Row) is positioned above this branch and now runs FIRST -
// confirmed by execution index in runs 8655 and 8657, not assumed - so the
// sale itself can be, and is, checked here. Leaving the old sentence in place
// would have told the operator a row was unverifiable at the exact moment it
// had just been verified.
//
// 'Confirm Purchase Row' throws on any non-duplicate failure, so reaching this
// node at all already means the sale is on file; its output says whether this
// run wrote it or found it already there.
const CLAIMED = [
  { node: 'Confirm Purchase Row', what: 'purchase_history row (the sale itself)', critical: true },
  { node: 'Supabase (Postgres) - Upsert Vector', what: 'deals_embeddings pgvector upsert', critical: true },
];

const NOT_VERIFIABLE_HERE = [];

function check(c) {
  let items;
  try { items = $(c.node).all(); }
  catch (e) { return { ...c, ok: false, why: 'node did not run on this branch' }; }
  if (!items.length) return { ...c, ok: false, why: 'node produced no items' };
  const j = items[0].json || {};
  if (j.error !== undefined) {
    const m = j.error && (j.error.message || j.error.description) || j.error;
    return { ...c, ok: false, why: String(m).slice(0, 300) };
  }
  return { ...c, ok: true };
}

const results  = CLAIMED.map(check);
const dropped  = results.filter(r => !r.ok);
const fatal    = dropped.filter(r => r.critical);

const status = fatal.length  ? 'FAILED'
             : dropped.length ? 'PARTIAL'
             : 'SUCCESS';

let deal = {};
try { deal = $('Format Deal Text').first().json || {}; } catch (e) { deal = {}; }

// The lead link is resolved in 'Attach Lead Id', NOT in Format Deal Text -
// Format Deal Text only carries a lead_id the CALLER posted, and the dashboard
// bundle live on Vercel posts none. Reading it from there reported null on run
// 8657 while the row being reported on carried lead_id 38. Read it from the
// node that decides it, and fall back to the posted value only if that node
// did not run at all.
let leadId = deal.lead_id ?? null;
try {
  const attached = $('Attach Lead Id').first().json || {};
  if (attached.lead_id !== undefined) leadId = attached.lead_id;
} catch (e) { /* purchase branch did not run; keep whatever was posted */ }

// What the purchase branch actually did, in its own words, so a repeat submit
// is reported as a repeat rather than as a fresh sale.
let purchaseRow = null;
try { purchaseRow = ($('Confirm Purchase Row').first().json || {}).purchase_row || null; } catch (e) { purchaseRow = null; }

return [{ json: {
  dealId: deal.dealId ?? null,
  customer_name: deal.customer_name ?? null,
  email: deal.email ?? null,
  lead_id: leadId,
  ...( $input.first().json || {} ),
  delivery: {
    status,
    verified: results.filter(r => r.ok).map(r => r.what),
    dropped:  dropped.map(r => r.what + ' - ' + r.why),
    not_verified: NOT_VERIFIABLE_HERE,
    purchase_row: purchaseRow,
    note: dropped.length
      ? dropped.length + ' of ' + results.length + ' claimed steps did not land'
      : 'all ' + results.length + ' claimed steps verified'
        + (purchaseRow && /already recorded/.test(purchaseRow) ? '; this deal was already on file and was not written twice' : ''),
  },
} }];

// -- INV-002, the half the client could not carry -------------------------
// purchase_history.lead_id is NULLABLE and means 'provenance not recorded'.
// It was only ever populated when the CALLER posted lead_id. The dashboard
// bundle live on Vercel does not post it, so every deal recorded from the
// real screen landed with a null link. This node resolves the link from the
// contact key instead, at the only place that can see the leads table.
//
// It is deliberately conservative:
//  * a posted lead_id is the operator's own assertion and wins outright;
//  * otherwise it links ONLY on an unambiguous match - exactly one lead whose
//    email equals the one being recorded, compared trimmed and lowercased;
//  * zero matches, more than one match, or a failed lookup leave it null.
// The lookup itself ran under the CALLER'S token, so a lead this user may not
// read is not a candidate and cannot be linked to. That is also why this node
// needs no tenant filter of its own: 'Lookup Lead By Email' deliberately does
// NOT use the service role, so tenant-scoped RLS on leads already applies to
// it. It is the one Supabase read in this system that was never cross-tenant.

const deal = $('Format Deal Text').first().json;

if (deal.lead_id) return [{ json: deal }];

const email = String(deal.email || '').trim().toLowerCase();

let rows = [];
try {
  rows = $input.all()
    .map(i => (i && i.json) || {})
    .filter(r => Number.isInteger(r.id) && r.id > 0 && r.email);
} catch (e) {
  rows = [];
}

const exact = rows.filter(r => String(r.email).trim().toLowerCase() === email);
const leadId = (email && exact.length === 1) ? exact[0].id : null;

// Exactly one item out, always: Record Purchase must run once per deal, and
// must still run when the lookup found nothing.
return [{ json: { ...deal, lead_id: leadId } }];

// -- Was the sale actually filed, and is a repeat a failure? --------------
// Record Purchase POSTs to /rest/v1/purchase_history with
// `Prefer: resolution=ignore-duplicates`. Both this workflow's notes and the
// deal form on the dashboard told the operator that this made re-recording the
// same deal a safe no-op. It did not. PostgREST honours that Prefer only on an
// UPSERT - one carrying `on_conflict` - and this is a plain INSERT, so the
// second submit of the same deal hit the partial unique index
// purchase_history_deal_id_key and came back 409 / SQLSTATE 23505. With
// onError = stopWorkflow that failed the entire execution and logged a FAILED
// audit row for a sale that was already on file. Observed live, execution 8655,
// 2 Sep 2026, from the real dashboard, on the second click of Record deal.
//
// `on_conflict=deal_id` is NOT the fix: that index is PARTIAL
// (WHERE deal_id IS NOT NULL) and Postgres cannot infer a partial index from
// the ON CONFLICT clause PostgREST emits. The duplicate is classified here
// instead, where the distinction can actually be made.
//
// A 409 on this endpoint means a row already exists under the same deal_id -
// precisely the outcome the caller asked for, and the table is protected by the
// unique index itself, not by the Prefer header. Anything else is a sale that
// did NOT reach the database and is re-thrown, so it still fails the run and
// still reaches the error workflow. Silence is never treated as success here.

const j = $input.first().json || {};

if (j.error === undefined) {
  return [{ json: { purchase_row: 'written' } }];
}

let blob;
try { blob = JSON.stringify(j); } catch (e) { blob = String(j); }

const isDuplicate = /23505|duplicate key|already exists/i.test(blob)
  || /"(httpCode|status)"\s*:\s*"?409\b/.test(blob);

if (isDuplicate) {
  return [{ json: { purchase_row: 'already recorded under the same deal_id - nothing written, nothing duplicated' } }];
}

throw new Error('purchase_history write FAILED and the sale is NOT on file: ' + blob.slice(0, 500));
